class LiquidPolicy {
    final double maxLevel;
    final double minLevel;
    final double refillThreshold;
    final double overflowMargin;
    final double maxStepUp;
    final double maxStepDown;
    final double leakSlopeThreshold;

    LiquidPolicy(double maxLevel, double minLevel,
                 double refillThreshold, double overflowMargin,
                 double maxStepUp, double maxStepDown,
                 double leakSlopeThreshold) {
        this.maxLevel = maxLevel;
        this.minLevel = minLevel;
        this.refillThreshold = refillThreshold;
        this.overflowMargin = overflowMargin;
        this.maxStepUp = maxStepUp;
        this.maxStepDown = maxStepDown;
        this.leakSlopeThreshold = leakSlopeThreshold;
    }

    boolean nearOverflow(double level) {
        return level > (maxLevel - overflowMargin);
    }
}

class LevelRecord {
    final double beforeLevel;
    final double delta;
    final double afterLevel;
    final String message;
    final List<String> warnings;

    LevelRecord(double beforeLevel, double delta, double afterLevel, String message, List<String> warnings) {
        this.beforeLevel = beforeLevel;
        this.delta = delta;
        this.afterLevel = afterLevel;
        this.message = message;
        this.warnings = warnings;
    }
}

class LevelAnomalyDetector {

    static List<String> detect(LiquidPolicy policy,
                               double before, double delta, double after,
                               List<LevelRecord> history) {
        List<String> warns = new ArrayList<>();

        if (delta > policy.maxStepUp)  warns.add("Surge: step increase > maxStepUp");
        if (delta < policy.maxStepDown) warns.add("Drop: step decrease < maxStepDown");

        if (after > policy.maxLevel) {
            warns.add("WARNING: Overflow Risk!");
        } else if (after < policy.minLevel) {
            warns.add("ALERT: Low Level! Refill Recommended.");
        } else {
            if (policy.nearOverflow(after)) warns.add("Caution: Near overflow margin");
            if (after < policy.refillThreshold) warns.add("Advice: Below refill threshold");
        }

        if (history.size() >= 2) {
            double d1 = history.get(history.size() - 1).delta;
            double d2 = history.get(history.size() - 2).delta;
            if (Math.signum(d1) != Math.signum(delta) && Math.abs(delta) > 300 && Math.abs(d1) > 300) {
                if (Math.signum(d2) == Math.signum(delta)) {
                    warns.add("Oscillation: alternating large deltas");
                }
            }
        }

        if (history.size() >= 8) {
            double slope = estimateSlope(history, 8);
            if (slope < -policy.leakSlopeThreshold) {
                warns.add("Leak tendency: negative trend detected");
            }
        }

        return warns;
    }

    private static double estimateSlope(List<LevelRecord> history, int k) {
        int n = Math.min(k, history.size());
        double sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
        for (int i = 0; i < n; i++) {
            double x = i;
            double y = history.get(history.size() - 1 - i).afterLevel;
            sumX += x; sumY += y; sumXY += x * y; sumX2 += x * x;
        }
        double denom = n * sumX2 - sumX * sumX;
        if (denom == 0) return 0;
        return (n * sumXY - sumX * sumY) / denom;
    }
}

class LiquidTankEx {
    private final LiquidPolicy policy;
    private double currentLevel;
    private final List<LevelRecord> log = new ArrayList<>();

    LiquidTankEx(LiquidPolicy policy, double initialLevel) {
        this.policy = policy;
        this.currentLevel = initialLevel;
    }

    public void updateLevel(double changeAmount) {
        double before = currentLevel;
        double after  = before + changeAmount;

        String base = String.format(Locale.US, "Before: %.2f L | Δ: %+,.2f L | Current Level: %.2f L",
                before, changeAmount, after);

        List<String> warns = LevelAnomalyDetector.detect(policy, before, changeAmount, after, log);
        StringBuilder sb = new StringBuilder(base);
        if (!warns.isEmpty()) {
            sb.append(" | ");
            for (int i = 0; i < warns.size(); i++) {
                if (i > 0) sb.append("; ");
                sb.append(warns.get(i));
            }
        }

        String line = sb.toString();
        System.out.println(line);
        currentLevel = after;
        log.add(new LevelRecord(before, changeAmount, after, line, warns));
    }

    public void printLevelLog() {
        System.out.println("\nLiquid Level Log:");
        for (LevelRecord r : log) {
            System.out.println(r.message);
        }
    }

    public LevelStats computeStats() {
        return LevelStats.from(log);
    }

    public void exportCsv(String filePath) throws IOException {
        try (PrintWriter pw = new PrintWriter(new BufferedWriter(new FileWriter(filePath)))) {
            pw.println("before,delta,after,has_warning,warnings");
            for (LevelRecord r : log) {
                String warn = String.join("|", r.warnings);
                pw.printf(Locale.US, "%.6f,%.6f,%.6f,%b,%s%n",
                        r.beforeLevel, r.delta, r.afterLevel, !r.warnings.isEmpty(), escapeCsv(warn));
            }
        }
    }

    private static String escapeCsv(String s) {
        if (s == null) return "";
        if (s.contains(",") || s.contains("\"")) {
            return "\"" + s.replace("\"", "\"\"") + "\"";
        }
        return s;
    }
}

class LevelStats {
    final int count;
    final double meanLevel, minLevel, maxLevel, p95Level;
    final double meanDelta, minDelta, maxDelta, p95Delta;

    LevelStats(int count, double meanLevel, double minLevel, double maxLevel, double p95Level,
               double meanDelta, double minDelta, double maxDelta, double p95Delta) {
        this.count = count;
        this.meanLevel = meanLevel;
        this.minLevel = minLevel;
        this.maxLevel = maxLevel;
        this.p95Level = p95Level;
        this.meanDelta = meanDelta;
        this.minDelta = minDelta;
        this.maxDelta = maxDelta;
        this.p95Delta = p95Delta;
    }

    static LevelStats from(List<LevelRecord> list) {
        if (list.isEmpty()) {
            return new LevelStats(0, Double.NaN, Double.NaN, Double.NaN, Double.NaN,
                    Double.NaN, Double.NaN, Double.NaN, Double.NaN);
        }
        List<Double> levels = new ArrayList<>();
        List<Double> deltas = new ArrayList<>();
        double minL = Double.POSITIVE_INFINITY, maxL = Double.NEGATIVE_INFINITY;
        double minD = Double.POSITIVE_INFINITY, maxD = Double.NEGATIVE_INFINITY;
        double sumL = 0, sumD = 0;

        for (LevelRecord r : list) {
            double l = r.afterLevel;
            double d = r.delta;
            levels.add(l);
            deltas.add(d);
            sumL += l; sumD += d;
            minL = Math.min(minL, l); maxL = Math.max(maxL, l);
            minD = Math.min(minD, d); maxD = Math.max(maxD, d);
        }

        double meanL = sumL / levels.size();
        double meanD = sumD / deltas.size();

        Collections.sort(levels);
        Collections.sort(deltas);
        double p95L = levels.get((int)Math.floor(0.95 * (levels.size()-1)));
        double p95D = deltas.get((int)Math.floor(0.95 * (deltas.size()-1)));

        return new LevelStats(list.size(), meanL, minL, maxL, p95L, meanD, minD, maxD, p95D);
    }
}

class LiquidSimulator {
    private final Random rnd = new Random(2025);

    double nextDelta() {
        double base = rnd.nextGaussian() * 150; // ~N(0,150)
        if (rnd.nextDouble() < 0.08) base += Math.signum(base) * (200 + rnd.nextDouble() * 400);
        return base;
    }
}

